import { Collapsible as BaseCollapsible } from "@base-ui/react/collapsible";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/collapsible.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

/**
 * Shows and hides one block of content. Use it for "show more" areas and
 * disclosure sections. For a list of related sections, use Accordion.
 */
export const Collapsible = BaseCollapsible.Root;

export function CollapsibleTrigger({ className, ...props }: StaticClass<typeof BaseCollapsible.Trigger>) {
  return <BaseCollapsible.Trigger className={cn("eui-collapsible__trigger", className)} {...props} />;
}

export function CollapsiblePanel({ className, ...props }: StaticClass<typeof BaseCollapsible.Panel>) {
  return <BaseCollapsible.Panel className={cn("eui-collapsible__panel", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Collapsible. The trigger is a full-width row. The panel fades in with a short slide. */

.eui-collapsible__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 40px;
  padding: 0 4px;
  border: 0;
  border-radius: var(--eui-radius-sm);
  background: transparent;
  color: var(--eui-color-fg);
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
}

.eui-collapsible__trigger:hover {
  background-color: var(--eui-color-hover);
}

.eui-collapsible__trigger:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-collapsible__trigger::after {
  content: "";
  width: 6px;
  height: 6px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg) translate(-2px, -2px);
  transition: transform var(--eui-duration-base) var(--eui-easing-out);
}

.eui-collapsible__trigger[aria-expanded="true"]::after {
  transform: rotate(-135deg) translate(-2px, -2px);
}

.eui-collapsible__panel {
  padding: 0 4px 8px;
  font-size: 14px;
  line-height: 20px;
  color: var(--eui-color-fg-muted);
  animation: eui-collapsible-in var(--eui-duration-base) var(--eui-easing-out);
}

@keyframes eui-collapsible-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .eui-collapsible__trigger::after,
  .eui-collapsible__panel {
    transition: none;
    animation: none;
  }
}
